package com.hotel.booking.dao;
import com.hotel.booking.config.DBConnection; import com.hotel.booking.model.Booking; import java.sql.*; import java.util.*;
public class BookingDAO {
 public boolean isRoomAvailable(int roomId,java.sql.Date in,java.sql.Date out)throws SQLException {String q="SELECT COUNT(*) FROM bookings WHERE room_id=? AND status='CONFIRMED' AND check_in < ? AND check_out > ?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,roomId);p.setDate(2,out);p.setDate(3,in);try(ResultSet r=p.executeQuery()){return r.next()&&r.getInt(1)==0;}}}
 public Booking add(Booking b)throws SQLException {String q="INSERT INTO bookings(customer_id,room_id,check_in,check_out,total_amount,status) VALUES(?,?,?,?,?,'CONFIRMED')";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setInt(1,b.getCustomerId());p.setInt(2,b.getRoomId());p.setDate(3,java.sql.Date.valueOf(b.getCheckIn()));p.setDate(4,java.sql.Date.valueOf(b.getCheckOut()));p.setBigDecimal(5,b.getTotalAmount());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){if(k.next())return new Booking(k.getInt(1),b.getCustomerId(),b.getRoomId(),b.getCheckIn(),b.getCheckOut(),b.getTotalAmount(),"CONFIRMED");}}return b;}
 public List<Booking> all()throws SQLException {List<Booking> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM bookings ORDER BY id")){while(r.next())out.add(map(r));}return out;}
 public boolean cancel(int id)throws SQLException {try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE bookings SET status='CANCELLED' WHERE id=? AND status='CONFIRMED'")){p.setInt(1,id);return p.executeUpdate()>0;}}
 private Booking map(ResultSet r)throws SQLException{return new Booking(r.getInt("id"),r.getInt("customer_id"),r.getInt("room_id"),r.getDate("check_in").toLocalDate(),r.getDate("check_out").toLocalDate(),r.getBigDecimal("total_amount"),r.getString("status"));}
}
